def to_dicts(columns, rows):
    columns = list(columns or [])
    if not columns:
        return []
    result = []
    for row in rows or []:
        values = list(row or [])
        record = {}
        for index, name in enumerate(columns):
            record[name] = values[index] if index < len(values) else None
        result.append(record)
    return result


def pick(records, fields):
    fields = list(fields or [])
    result = []
    for record in records or []:
        item = {}
        for field in fields:
            item[field] = (record or {}).get(field)
        result.append(item)
    return result


def build_limit(limit, offset):
    ok_limit = isinstance(limit, int) and not isinstance(limit, bool) and 1 <= limit <= 100
    ok_offset = isinstance(offset, int) and not isinstance(offset, bool) and offset >= 0
    return 'LIMIT ? OFFSET ?', [limit if ok_limit else 20, offset if ok_offset else 0]


cols = ['id', 'name', 'score']
print(to_dicts(cols, [(1, '小明', 88), (2, '小红')]))
print(pick(to_dicts(cols, [(1, '小明', 88), (2, '小红')]), ['name', 'id']))
print(build_limit(50, 0))
print(build_limit(-1, 'abc'))
